  // zero-length interval could return holders that are only trimmed at the start (but not at the end), because
  // Interval#overlaps does not consider a zero-length interval overlapping when its start instant is shared.
  if (Intervals.isEmpty(interval)) {
    return retVal;
  }

  final boolean queryIsEternity = Intervals.isEternity(interval);

